import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectMemberRepo from "@/server/repositories/project-member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import { hasRoleAtLeast } from "@/types/member";
import {
  actorEnvelope,
  NotFoundError,
  orgResource,
  projectResource,
  requireFound,
} from "./_support";
import type {
  ArchiveProjectInput,
  CreateProjectInput,
  ListProjectsInput,
  UpdateProjectInput,
} from "@/schemas/project";
import type { OrgId, Page, ProjectId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { Project, ProjectWithStats } from "@/types/project";

/**
 * Visibility gate for `private` projects: visible to admins/owners, platform
 * staff, the project's lead, or an explicit project member. `org` and
 * `public` projects are visible to the whole organization, unaffected.
 */
export async function canViewProject(
  actor: Actor,
  project: Project,
): Promise<boolean> {
  if (actor.orgId !== project.orgId) return false;
  if (project.visibility !== "private") return true;
  if (actor.isPlatformStaff === true) return true;
  if (hasRoleAtLeast(actor.role, "admin")) return true;
  if (project.leadId !== null && project.leadId === actor.userId) return true;

  return projectMemberRepo.isProjectMember(
    project.orgId,
    project.id,
    actor.userId,
  );
}

/**
 * A private project the actor cannot see must behave as if it did not
 * exist — a `NotFoundError`, never a permission error.
 */
async function assertProjectVisible(
  actor: Actor,
  project: Project,
  entity: string,
  id: string,
): Promise<void> {
  if (!(await canViewProject(actor, project))) {
    throw new NotFoundError(entity, id);
  }
}

/**
 * Ids of the org's `private` projects hidden from `actor` — empty for an
 * admin, owner, platform staff member, or anyone who can already see every
 * private project. Backs the visibility filter behind project and issue
 * listings.
 */
export async function listHiddenProjectIds(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly ProjectId[]> {
  if (actor.isPlatformStaff === true || hasRoleAtLeast(actor.role, "admin")) {
    return [];
  }

  const privateProjects = await projectRepo.listPrivateProjects(orgId);
  if (privateProjects.length === 0) return [];

  const visible = new Set<ProjectId>(
    privateProjects
      .filter((project) => project.leadId === actor.userId)
      .map((project) => project.id),
  );

  const remaining = privateProjects
    .map((project) => project.id)
    .filter((id) => !visible.has(id));

  const memberOf = await projectMemberRepo.listMemberProjectIds(
    orgId,
    actor.userId,
    remaining,
  );
  for (const id of memberOf) visible.add(id);

  return privateProjects
    .map((project) => project.id)
    .filter((id) => !visible.has(id));
}

/**
 * Creates a project once the plan still has room for one. The key is derived
 * from the name when the caller left it blank, so the issue numbering scheme
 * (`TF-12`) is never invented at the call site.
 */
export async function createProject(
  actor: Actor,
  input: CreateProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "project:create", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const used = await projectRepo.countProjects(input.orgId);
  if (wouldExceedLimit(org.plan, "projects", used)) {
    throw new Error(
      `Plan ${org.plan} allows ${used} projects; upgrade to add another`,
    );
  }

  const slug = await suggestProjectSlug(input.orgId, input.name);

  const project = await projectRepo.insertProject({
    ...input,
    slug,
    key: input.key || projectKeyFromName(input.name),
  });

  await emit("project.created", {
    ...actorEnvelope(actor),
    projectId: project.id,
    name: project.name,
    slug: project.slug,
  });

  return project;
}

