import { afterAll, beforeAll, describe, expect, it } from "vitest";

vi_mock();
function vi_mock() {}

import { NotFoundError } from "@/server/services/_support";
import * as projectMemberRepo from "@/server/repositories/project-member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as commentService from "@/server/services/comment-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Project } from "@/types/project";

let cleanup: () => void;
let tenant: Tenant;
let privateProject: Project;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("privviz", "growth");

  privateProject = await projectService.createProject(tenant.actors.owner, {
    orgId: tenant.org.id,
    name: "Secret Ops",
    slug: "secret-ops",
    key: "SEC",
    description: null,
    visibility: "private",
    leadId: tenant.userIds.member,
    color: "#111111",
    targetDate: null,
  });
});

afterAll(() => {
  cleanup();
});

describe("private project visibility", () => {
  it("canViewProject: role-based access", async () => {
    expect(await projectService.canViewProject(tenant.actors.owner, privateProject)).toBe(true);
    expect(await projectService.canViewProject(tenant.actors.admin, privateProject)).toBe(true);
    expect(await projectService.canViewProject(tenant.actors.member, privateProject)).toBe(true); // lead
    expect(await projectService.canViewProject(tenant.actors.viewer, privateProject)).toBe(false);
    expect(
      await projectService.canViewProject(
        { ...tenant.actors.viewer, isPlatformStaff: true },
        privateProject,
      ),
    ).toBe(true);
  });

  it("project membership grants visibility immediately", async () => {
    expect(await projectService.canViewProject(tenant.actors.viewer, privateProject)).toBe(false);
    await projectMemberRepo.addProjectMember(
      tenant.org.id,
      privateProject.id,
      tenant.userIds.viewer,
    );
    expect(await projectService.canViewProject(tenant.actors.viewer, privateProject)).toBe(true);
    await projectMemberRepo.removeProjectMember(
      tenant.org.id,
      privateProject.id,
      tenant.userIds.viewer,
    );
    expect(await projectService.canViewProject(tenant.actors.viewer, privateProject)).toBe(false);
  });

  it("getProject 404s for an outsider, not a permission error", async () => {
    await expect(
      projectService.getProject(tenant.actors.viewer, tenant.org.id, privateProject.slug),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("updateProject 404s for an outsider even when role would otherwise allow it", async () => {
    // `member` role passes the project:update role check but not visibility.
    const outsiderMember = { ...tenant.actors.viewer, role: "member" as const };
    await expect(
      projectService.updateProject(outsiderMember, {
        orgId: tenant.org.id,
        projectId: privateProject.id,
        name: "Hacked",
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    const stillSame = await projectRepo.findProjectById(tenant.org.id, privateProject.id);
    expect(stillSame?.name).toBe("Secret Ops");
  });

  it("listProjects excludes the private project and total drops by one", async () => {
    const asOutsider = await projectService.listProjects(tenant.actors.viewer, {
      orgId: tenant.org.id,
      limit: 25,
    });
    const asAdmin = await projectService.listProjects(tenant.actors.admin, {
      orgId: tenant.org.id,
      limit: 25,
    });

    expect(asOutsider.items.some((p) => p.project.id === privateProject.id)).toBe(false);
    expect(asAdmin.items.some((p) => p.project.id === privateProject.id)).toBe(true);
    expect(asAdmin.total).toBe(asOutsider.total + 1);
  });

  it("issue-service 404s for an outsider on every entry point", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member, // the lead
      issueInput(tenant.org.id, privateProject.id, { title: "classified" }),
    );

    await expect(
      issueService.createIssue(
        tenant.actors.viewer,
        issueInput(tenant.org.id, privateProject.id, { title: "nope" }),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      issueService.getIssue(tenant.actors.viewer, tenant.org.id, issue.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      issueService.getBoard(tenant.actors.viewer, tenant.org.id, privateProject.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      issueService.archiveIssue(tenant.actors.viewer, tenant.org.id, issue.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    const orgWide = await issueService.listIssues(tenant.actors.viewer, {
      orgId: tenant.org.id,
      limit: 25,
    });
    expect(orgWide.items.some((i) => i.id === issue.id)).toBe(false);

    const orgWideAsAdmin = await issueService.listIssues(tenant.actors.admin, {
      orgId: tenant.org.id,
      limit: 25,
    });
    expect(orgWideAsAdmin.items.some((i) => i.id === issue.id)).toBe(true);
  });

  it("comment-service 404s for an outsider", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, privateProject.id, { title: "secret issue for comments" }),
    );

    const comment = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "hush hush",
      parentId: null,
      mentionedUserIds: [],
    });

    await expect(
      commentService.getThread(tenant.actors.viewer, tenant.org.id, issue.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      commentService.createComment(tenant.actors.viewer, {
        orgId: tenant.org.id,
        issueId: issue.id,
        body: "sneaking in",
        parentId: null,
        mentionedUserIds: [],
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      commentService.updateComment(tenant.actors.viewer, {
        orgId: tenant.org.id,
        commentId: comment.id,
        body: "edited by outsider",
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      commentService.deleteComment(tenant.actors.viewer, {
        orgId: tenant.org.id,
        commentId: comment.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    // sanity: the lead (who created it) can still read the thread
    const thread = await commentService.getThread(tenant.actors.member, tenant.org.id, issue.id);
    expect(thread.length).toBeGreaterThan(0);
  });

  it("org and public projects are unaffected", async () => {
    expect(await projectService.canViewProject(tenant.actors.viewer, tenant.project)).toBe(true);
  });
});
